import math


def convert_celsius(value):
    """Convert a finite Celsius int/float (not bool) to Fahrenheit."""
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError("temperature must be a finite int or float")
    if not math.isfinite(value):
        raise ValueError("temperature must be finite")
    return value * 9 / 5 + 32

def normalize_tags(values):
    """Strip, casefold, drop empties and dedupe tags in input order."""
    if not isinstance(values, list):
        raise ValueError("tags must be a list of strings")
    seen = set()
    result = []
    for value in values:
        if not isinstance(value, str):
            raise ValueError("every tag must be a string")
        tag = value.strip().casefold()
        if not tag or tag in seen:
            continue
        seen.add(tag)
        result.append(tag)
    return result
